module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg areset;
    reg in;
    wire out;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .in(in),
        .out(out)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to check output against expected value using case inequality (!==)
    task check_output;
        input expected;
        begin
            @(posedge clk);
            #1; // Small delay to sample after clock edge
            if (out !== expected) begin
                $display("Mismatch: time=%0t, in=%b, out=%b (expected %b)", $time, in, out, expected);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        in = 0;

        // Test 1: Asynchronous reset test
        areset = 1;
        #3;
        // State should be B (out = 1) immediately upon asynchronous reset, regardless of clk
        if (out !== 1'b1) begin
            $display("Async Reset Mismatch: time=%0t, out=%b (expected 1)", $time, out);
            errors = errors + 1;
        end

        // Deassert reset
        areset = 0;
        #2;

        // At this point state is B (out=1).
        // Moore machine spec:
        // State B (1) --0--> A (0)
        // State B (1) --1--> B (1)
        // State A (0) --0--> B (1)
        // State A (0) --1--> A (0)

        // Test vector sequence:
        // Current state: B (out = 1)
        // Apply in = 1 -> should stay in B (out = 1)
        in = 1'b1;
        check_output(1'b1);

        // Current state: B (out = 1)
        // Apply in = 0 -> should go to A (out = 0)
        in = 1'b0;
        check_output(1'b0);

        // Current state: A (out = 0)
        // Apply in = 1 -> should stay in A (out = 0)
        in = 1'b1;
        check_output(1'b0);

        // Current state: A (out = 0)
        // Apply in = 0 -> should go to B (out = 1)
        in = 1'b0;
        check_output(1'b1);

        // Current state: B (out = 1)
        // Apply in = 0 -> should go to A (out = 0)
        in = 1'b0;
        check_output(1'b0);

        // Test asynchronous reset recovery again mid-operation
        areset = 1;
        #4;
        if (out !== 1'b1) begin
            $display("Mid-operation Async Reset Mismatch: time=%0t, out=%b (expected 1)", $time, out);
            errors = errors + 1;
        end
        areset = 0;
        #1;

        // Final check results
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
